	/** OrientationLabel groups the details about orientation and reading order. */
	export interface GoodocOrientationLabel {

		/**
		 * After rotating so that the text orientation is upright, how many radians does one have to rotate the block anti-clockwise for it to be level? We guarantee: -Pi/4 <= deskew_angle <= Pi/4
		 * Type: float
		 */
		deskewAngle?: number | null;

		/** Whether a text line is mirrored (e.g. reflected in a shiny surface or seen through the opposite side of a storefront window). The intent is that this is a quality of the text line image. It needs to be reflected according to a vertical axis along the direction of upright characters to make it readable. This does not affect the shape of the bounding box. A mirrored line with top to bottom writing remains top to bottom. A mirrored horizontal line will flip left to right. However any child entities (symbols) will remain in the same order, and the writing direction imposed by the language (ltr or rtl) will remain the same. */
		mirrored?: boolean | null;
		orientation?: GoodocOrientationLabelOrientation | null;
		textlineOrder?: GoodocOrientationLabelTextlineOrder | null;
		writingDirection?: GoodocOrientationLabelWritingDirection | null;
	}

	/** OrientationLabel groups the details about orientation and reading order. */
	export interface GoodocOrientationLabelFormProperties {

		/**
		 * After rotating so that the text orientation is upright, how many radians does one have to rotate the block anti-clockwise for it to be level? We guarantee: -Pi/4 <= deskew_angle <= Pi/4
		 * Type: float
		 */
		deskewAngle: FormControl<number | null | undefined>,

		/** Whether a text line is mirrored (e.g. reflected in a shiny surface or seen through the opposite side of a storefront window). The intent is that this is a quality of the text line image. It needs to be reflected according to a vertical axis along the direction of upright characters to make it readable. This does not affect the shape of the bounding box. A mirrored line with top to bottom writing remains top to bottom. A mirrored horizontal line will flip left to right. However any child entities (symbols) will remain in the same order, and the writing direction imposed by the language (ltr or rtl) will remain the same. */
		mirrored: FormControl<boolean | null | undefined>,
		orientation: FormControl<GoodocOrientationLabelOrientation | null | undefined>,
		textlineOrder: FormControl<GoodocOrientationLabelTextlineOrder | null | undefined>,
		writingDirection: FormControl<GoodocOrientationLabelWritingDirection | null | undefined>,
	}
	export function CreateGoodocOrientationLabelFormGroup() {
		return new FormGroup<GoodocOrientationLabelFormProperties>({
			deskewAngle: new FormControl<number | null | undefined>(undefined),
			mirrored: new FormControl<boolean | null | undefined>(undefined),
			orientation: new FormControl<GoodocOrientationLabelOrientation | null | undefined>(undefined),
			textlineOrder: new FormControl<GoodocOrientationLabelTextlineOrder | null | undefined>(undefined),
			writingDirection: new FormControl<GoodocOrientationLabelWritingDirection | null | undefined>(undefined),
		});

	}

	export enum GoodocOrientationLabelOrientation { ORIENTATION_PAGE_UP = 'ORIENTATION_PAGE_UP', ORIENTATION_PAGE_RIGHT = 'ORIENTATION_PAGE_RIGHT', ORIENTATION_PAGE_DOWN = 'ORIENTATION_PAGE_DOWN', ORIENTATION_PAGE_LEFT = 'ORIENTATION_PAGE_LEFT' }

	export enum GoodocOrientationLabelTextlineOrder { TEXTLINE_ORDER_LEFT_TO_RIGHT = 'TEXTLINE_ORDER_LEFT_TO_RIGHT', TEXTLINE_ORDER_RIGHT_TO_LEFT = 'TEXTLINE_ORDER_RIGHT_TO_LEFT', TEXTLINE_ORDER_TOP_TO_BOTTOM = 'TEXTLINE_ORDER_TOP_TO_BOTTOM' }

	export enum GoodocOrientationLabelWritingDirection { WRITING_DIRECTION_LEFT_TO_RIGHT = 'WRITING_DIRECTION_LEFT_TO_RIGHT', WRITING_DIRECTION_RIGHT_TO_LEFT = 'WRITING_DIRECTION_RIGHT_TO_LEFT', WRITING_DIRECTION_TOP_TO_BOTTOM = 'WRITING_DIRECTION_TOP_TO_BOTTOM' }


