	/** Data streams refer to additional data separate from audio and video streams For example: camera motion metadata (see http://go/wally-format) Available tags: 4+ */
	export interface VideoVideoStreamInfoDataStream {
		codecFourcc?: string | null;

		/** Codec information */
		codecId?: VideoVideoStreamInfoAudioCodecId | null;
		streamCodecTag?: string | null;

		/** Index of the stream in the file */
		streamIndex?: string | null;
	}

	/** Data streams refer to additional data separate from audio and video streams For example: camera motion metadata (see http://go/wally-format) Available tags: 4+ */
	export interface VideoVideoStreamInfoDataStreamFormProperties {
		codecFourcc: FormControl<string | null | undefined>,

		/** Codec information */
		codecId: FormControl<VideoVideoStreamInfoAudioCodecId | null | undefined>,
		streamCodecTag: FormControl<string | null | undefined>,

		/** Index of the stream in the file */
		streamIndex: FormControl<string | null | undefined>,
	}
	export function CreateVideoVideoStreamInfoDataStreamFormGroup() {
		return new FormGroup<VideoVideoStreamInfoDataStreamFormProperties>({
			codecFourcc: new FormControl<string | null | undefined>(undefined),
			codecId: new FormControl<VideoVideoStreamInfoAudioCodecId | null | undefined>(undefined),
			streamCodecTag: new FormControl<string | null | undefined>(undefined),
			streamIndex: new FormControl<string | null | undefined>(undefined),
		});

	}


